//! Configuration for the tex-fmt run.

#[derive(Clone, Debug)]
pub struct Args {
    pub check: bool,
    pub print: bool,
    pub fail_on_change: bool,
    pub wrap: bool,
    pub wraplen: usize,
    pub wrapmin: usize,
    pub tabsize: usize,
    pub tabchar: TabChar,
    pub stdin: bool,
    pub config_path: Option<String>,
    pub verbosity: Verbosity,
    pub lists: Vec<String>,
    pub verbatims: Vec<String>,
    pub no_indent_envs: Vec<String>,
    pub wrap_chars: Vec<char>,
    pub recursive: bool,
    pub files: Vec<String>,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum TabChar {
    Space,
    Tab,
}

impl TabChar {
    pub fn as_str(self) -> &'static str {
        match self {
            TabChar::Space => "space",
            TabChar::Tab => "tab",
        }
    }
}

#[derive(Clone, Copy, Debug, PartialEq, Eq, PartialOrd, Ord)]
pub enum Verbosity {
    Error,
    Warn,
    Info,
    Trace,
}

impl Verbosity {
    pub fn as_str(self) -> &'static str {
        match self {
            Verbosity::Error => "error",
            Verbosity::Warn => "warn",
            Verbosity::Info => "info",
            Verbosity::Trace => "trace",
        }
    }
}

impl Default for Args {
    fn default() -> Self {
        Self {
            check: false,
            print: false,
            fail_on_change: false,
            wrap: true,
            wraplen: 80,
            wrapmin: 70,
            tabsize: 2,
            tabchar: TabChar::Space,
            stdin: false,
            config_path: None,
            verbosity: Verbosity::Warn,
            lists: vec![
                "itemize".to_string(),
                "enumerate".to_string(),
                "description".to_string(),
                "inlineroman".to_string(),
                "inventory".to_string(),
            ],
            verbatims: vec![
                "verbatim".to_string(),
                "Verbatim".to_string(),
                "lstlisting".to_string(),
                "minted".to_string(),
                "comment".to_string(),
            ],
            no_indent_envs: vec!["document".to_string()],
            wrap_chars: vec![],
            recursive: false,
            files: vec![],
        }
    }
}

impl Args {
    pub fn recalc_wrapmin(&mut self) {
        if self.wraplen >= 50 {
            self.wrapmin = self.wraplen - 10;
        } else {
            self.wrapmin = self.wraplen;
        }
    }

    /// Produce the textual dump for `--args`.
    pub fn format_args_display(&self, show_files: bool) -> String {
        let mut s = String::new();
        s.push_str("tex-fmt\n");
        let put = |s: &mut String, key: &str, val: &str| {
            let padded = format!("{:<25}", format!("{}:", key));
            s.push_str("  ");
            s.push_str(&padded);
            s.push_str(val);
            s.push('\n');
        };
        put(&mut s, "check", &self.check.to_string());
        put(&mut s, "print", &self.print.to_string());
        put(&mut s, "fail-on-change", &self.fail_on_change.to_string());
        put(&mut s, "wrap", &self.wrap.to_string());
        put(&mut s, "wraplen", &self.wraplen.to_string());
        put(&mut s, "wrapmin", &self.wrapmin.to_string());
        put(&mut s, "tabsize", &self.tabsize.to_string());
        put(&mut s, "tabchar", self.tabchar.as_str());
        put(&mut s, "stdin", &self.stdin.to_string());
        match &self.config_path {
            None => put(&mut s, "config", "None"),
            Some(p) => put(&mut s, "config", p),
        }
        put(&mut s, "verbosity", self.verbosity.as_str());
        put_list(&mut s, "lists", &self.lists);
        put_list(&mut s, "verbatims", &self.verbatims);
        put_list(&mut s, "no-indent-envs", &self.no_indent_envs);
        let wrap_chars_strs: Vec<String> = self.wrap_chars.iter().map(|c| c.to_string()).collect();
        put_list(&mut s, "wrap-chars", &wrap_chars_strs);
        if show_files {
            put_list(&mut s, "files", &self.files);
        }
        s
    }
}

fn put_list(s: &mut String, key: &str, items: &[String]) {
    let padded = format!("{:<25}", format!("{}:", key));
    s.push_str("  ");
    s.push_str(&padded);
    if items.is_empty() {
        s.push(' ');
        s.push('\n');
    } else {
        for (i, item) in items.iter().enumerate() {
            if i == 0 {
                s.push_str(item);
            } else {
                s.push_str("                           ");
                s.push_str(item);
            }
            s.push('\n');
        }
    }
}
EOF

