//! Logging for tex-fmt.

use crate::args::Verbosity;
use std::io::Write;
use std::sync::OnceLock;

static VERBOSITY: OnceLock<Verbosity> = OnceLock::new();

pub fn init(v: Verbosity) {
    let _ = VERBOSITY.set(v);
}

fn current() -> Verbosity {
    *VERBOSITY.get().unwrap_or(&Verbosity::Warn)
}

fn emit(level: Verbosity, label: &str, file: &str, msg: &str) {
    if current() < level {
        return;
    }
    // Format: `LEVEL: tex-fmt FILE: MSG \n`
    let file_str = if file.is_empty() {
        String::new()
    } else {
        file.to_string()
    };
    let header = format!("{}: tex-fmt {}: {} ", label, file_str, msg);
    let _ = writeln!(std::io::stderr(), "{}", header.trim_end_matches(' '));
    // match the observed format with trailing space: "ERROR: tex-fmt X: MSG "
    // We'll actually match the output they use: with trailing space
}

pub fn error(file: &str, msg: &str) {
    let header = format!("ERROR: tex-fmt {}: {} ", file, msg);
    let _ = writeln!(std::io::stderr(), "{}", header);
}

pub fn warn(file: &str, msg: &str) {
    if current() < Verbosity::Warn {
        return;
    }
    let header = format!("WARN: tex-fmt {}: {} ", file, msg);
    let _ = writeln!(std::io::stderr(), "{}", header);
}

pub fn info(file: &str, msg: &str) {
    if current() < Verbosity::Info {
        return;
    }
    let header = format!("INFO: tex-fmt {}: {} ", file, msg);
    let _ = writeln!(std::io::stderr(), "{}", header);
}

pub fn trace(file: &str, msg: &str) {
    if current() < Verbosity::Trace {
        return;
    }
    let header = format!("TRACE: tex-fmt {}: {} ", file, msg);
    let _ = writeln!(std::io::stderr(), "{}", header);
}

#[allow(dead_code)]
pub fn raw(level: Verbosity, file: &str, msg: &str) {
    match level {
        Verbosity::Error => error(file, msg),
        Verbosity::Warn => warn(file, msg),
        Verbosity::Info => info(file, msg),
        Verbosity::Trace => trace(file, msg),
    }
    let _ = emit;
}
EOF

