//! Minimal TOML-style config reader.

use crate::args::{Args, TabChar, Verbosity};
use std::fs;
use std::path::{Path, PathBuf};

pub fn apply_config(args: &mut Args) -> Result<(), String> {
    let path = find_config_path(&args.config_path)?;
    if let Some(p) = path {
        if let Ok(content) = fs::read_to_string(&p) {
            parse_and_apply(args, &content)?;
        }
    }
    Ok(())
}

fn find_config_path(explicit: &Option<String>) -> Result<Option<PathBuf>, String> {
    if let Some(ref p) = explicit {
        let pb = PathBuf::from(p);
        if !pb.exists() {
            return Err(format!("Config file {} not found.", p));
        }
        return Ok(Some(pb));
    }

    // Look in cwd
    let cwd = PathBuf::from("tex-fmt.toml");
    if cwd.exists() {
        return Ok(Some(cwd));
    }

    // Git repo root
    if let Some(gitroot) = git_root() {
        let p = gitroot.join("tex-fmt.toml");
        if p.exists() {
            return Ok(Some(p));
        }
    }

    // User config dir
    if let Ok(home) = std::env::var("HOME") {
        let p = Path::new(&home).join(".config").join("tex-fmt").join("tex-fmt.toml");
        if p.exists() {
            return Ok(Some(p));
        }
    }
    if let Ok(xdg) = std::env::var("XDG_CONFIG_HOME") {
        let p = Path::new(&xdg).join("tex-fmt").join("tex-fmt.toml");
        if p.exists() {
            return Ok(Some(p));
        }
    }

    Ok(None)
}

fn git_root() -> Option<PathBuf> {
    let mut cur = std::env::current_dir().ok()?;
    loop {
        if cur.join(".git").exists() {
            return Some(cur);
        }
        if !cur.pop() {
            return None;
        }
    }
}

fn parse_and_apply(args: &mut Args, content: &str) -> Result<(), String> {
    for line_raw in content.lines() {
        let line = line_raw.trim();
        if line.is_empty() || line.starts_with('#') {
            continue;
        }
        let (key, val) = match line.split_once('=') {
            Some(kv) => kv,
            None => continue,
        };
        let key = key.trim();
        let val = val.trim().trim_end_matches('#').trim();
        match key {
            "check" => args.check = parse_bool(val)?,
            "print" => args.print = parse_bool(val)?,
            "fail-on-change" => args.fail_on_change = parse_bool(val)?,
            "wrap" => args.wrap = parse_bool(val)?,
            "wraplen" => {
                args.wraplen = parse_usize(val)?;
                args.recalc_wrapmin();
            }
            "wrapmin" => args.wrapmin = parse_usize(val)?,
            "tabsize" => args.tabsize = parse_usize(val)?,
            "tabchar" => {
                let s = strip_string(val)?;
                args.tabchar = match s.as_str() {
                    "space" => TabChar::Space,
                    "tab" => TabChar::Tab,
                    _ => return Err(format!("invalid tabchar: {}", s)),
                };
            }
            "stdin" => args.stdin = parse_bool(val)?,
            "lists" => args.lists = parse_string_array(val)?,
            "verbatims" => args.verbatims = parse_string_array(val)?,
            "no-indent-envs" => args.no_indent_envs = parse_string_array(val)?,
            "wrap-chars" => {
                let strs = parse_string_array(val)?;
                let mut chars = Vec::new();
                for s in strs {
                    if let Some(c) = s.chars().next() {
                        chars.push(c);
                    }
                }
                args.wrap_chars = chars;
            }
            "verbosity" => {
                let s = strip_string(val)?;
                args.verbosity = match s.as_str() {
                    "error" => Verbosity::Error,
                    "warn" => Verbosity::Warn,
                    "info" => Verbosity::Info,
                    "trace" => Verbosity::Trace,
                    _ => return Err(format!("invalid verbosity: {}", s)),
                };
            }
            _ => {}
        }
    }
    Ok(())
}

fn parse_bool(v: &str) -> Result<bool, String> {
    match v {
        "true" => Ok(true),
        "false" => Ok(false),
        _ => Err(format!("expected bool, got {}", v)),
    }
}

fn parse_usize(v: &str) -> Result<usize, String> {
    v.parse::<usize>().map_err(|e| e.to_string())
}

fn strip_string(v: &str) -> Result<String, String> {
    let v = v.trim();
    if (v.starts_with('"') && v.ends_with('"'))
        || (v.starts_with('\'') && v.ends_with('\''))
    {
        Ok(v[1..v.len() - 1].to_string())
    } else {
        Err(format!("expected string, got {}", v))
    }
}

fn parse_string_array(v: &str) -> Result<Vec<String>, String> {
    let v = v.trim();
    if !(v.starts_with('[') && v.ends_with(']')) {
        return Err(format!("expected array, got {}", v));
    }
    let inner = &v[1..v.len() - 1];
    let mut result = Vec::new();
    let mut depth = 0;
    let mut in_str = false;
    let mut quote = '"';
    let mut cur = String::new();
    for c in inner.chars() {
        if in_str {
            cur.push(c);
            if c == quote {
                in_str = false;
            }
        } else if c == '"' || c == '\'' {
            in_str = true;
            quote = c;
            cur.push(c);
        } else if c == '[' {
            depth += 1;
            cur.push(c);
        } else if c == ']' {
            depth -= 1;
            cur.push(c);
        } else if c == ',' && depth == 0 {
            let s = cur.trim();
            if !s.is_empty() {
                result.push(strip_string(s)?);
            }
            cur.clear();
        } else {
            cur.push(c);
        }
    }
    let s = cur.trim();
    if !s.is_empty() {
        result.push(strip_string(s)?);
    }
    Ok(result)
}
