cat > src/cli.rs <<'EOF'
//! CLI parsing and dispatch.

use crate::args::{Args, TabChar, Verbosity};
use crate::{completion, config, format, logger, man};
use std::io::{self, Read, Write};
use std::path::PathBuf;
use std::process::ExitCode;

pub fn run() -> ExitCode {
    let argv: Vec<String> = std::env::args().collect();
    let prog = argv.first().cloned().unwrap_or_else(|| "tex-fmt".to_string());
    let prog_basename = std::path::Path::new(&prog)
        .file_name()
        .map(|s| s.to_string_lossy().to_string())
        .unwrap_or_else(|| "tex-fmt".to_string());

    let mut iter = argv.iter().skip(1);

    let mut args = Args::default();
    let mut want_help = false;
    let mut want_version = false;
    let mut want_args = false;
    let mut want_man = false;
    let mut completion_shell: Option<String> = None;
    let mut no_config = false;
    let mut noconfig_set = false;
    let mut wrap_set = false; // --nowrap used
    let mut cli_wraplen = false;
    let mut cli_wrapmin = false;
    let mut cli_tabsize = false;
    let mut cli_tabchar = false;
    let mut cli_stdin = false;
    let mut cli_verbosity = false;
    let mut cli_check = false;
    let mut cli_print = false;
    let mut cli_fail = false;
    let mut cli_recursive = false;

    let _ = noconfig_set;
    let _ = wrap_set;

    let mut positional = Vec::new();
    let mut only_positional = false;

    while let Some(tok_raw) = iter.next() {
        let tok = tok_raw.as_str();
        if only_positional {
            positional.push(tok.to_string());
            continue;
        }
        if tok == "--" {
            only_positional = true;
            continue;
        }
        // Long options possibly with =val
        if let Some(stripped) = tok.strip_prefix("--") {
            let (name, inline_val) = match stripped.split_once('=') {
                Some((n, v)) => (n, Some(v.to_string())),
                None => (stripped, None),
            };
            match name {
                "check" => {
                    args.check = true;
                    cli_check = true;
                }
                "print" => {
                    args.print = true;
                    cli_print = true;
                }
                "fail-on-change" => {
                    args.fail_on_change = true;
                    cli_fail = true;
                }
                "nowrap" => {
                    args.wrap = false;
                    wrap_set = true;
                }
                "wraplen" => {
                    let v = match inline_val {
                        Some(v) => v,
                        None => match iter.next() {
                            Some(v) => v.clone(),
                            None => {
                                return clap_err_missing(&prog_basename, "--wraplen <N>");
                            }
                        },
                    };
                    match v.parse::<usize>() {
                        Ok(n) => {
                            args.wraplen = n;
                            args.recalc_wrapmin();
                            cli_wraplen = true;
                        }
                        Err(e) => {
                            return clap_err_invalid(
                                &prog_basename,
                                "--wraplen <N>",
                                &v,
                                &e.to_string(),
                            );
                        }
                    }
                }
                "tabsize" => {
                    let v = match inline_val {
                        Some(v) => v,
                        None => match iter.next() {
                            Some(v) => v.clone(),
                            None => {
                                return clap_err_missing(&prog_basename, "--tabsize <N>");
                            }
                        },
                    };
                    match v.parse::<usize>() {
                        Ok(n) => {
                            args.tabsize = n;
                            cli_tabsize = true;
                        }
                        Err(e) => {
                            return clap_err_invalid(
                                &prog_basename,
                                "--tabsize <N>",
                                &v,
                                &e.to_string(),
                            );
                        }
                    }
                }
                "usetabs" => {
                    args.tabchar = TabChar::Tab;
                    cli_tabchar = true;
                }
                "stdin" => {
                    args.stdin = true;
                    cli_stdin = true;
                }
                "config" => {
                    let v = match inline_val {
                        Some(v) => v,
                        None => match iter.next() {
                            Some(v) => v.clone(),
                            None => {
                                return clap_err_missing(&prog_basename, "--config <PATH>");
                            }
                        },
                    };
                    args.config_path = Some(v);
                }
                "noconfig" => {
                    no_config = true;
                    noconfig_set = true;
                }
                "verbose" => {
                    if args.verbosity < Verbosity::Info {
                        args.verbosity = Verbosity::Info;
                    }
                    cli_verbosity = true;
                }
                "quiet" => {
                    args.verbosity = Verbosity::Error;
                    cli_verbosity = true;
                }
                "trace" => {
                    args.verbosity = Verbosity::Trace;
                    cli_verbosity = true;
                }
                "completion" => {
                    let v = match inline_val {
                        Some(v) => v,
                        None => match iter.next() {
                            Some(v) => v.clone(),
                            None => {
                                return clap_err_missing(&prog_basename, "--completion <SHELL>");
                            }
                        },
                    };
                    completion_shell = Some(v);
                }
                "man" => {
                    want_man = true;
                }
                "args" => {
                    want_args = true;
                }
                "recursive" => {
                    args.recursive = true;
                    cli_recursive = true;
                }
                "help" => {
                    want_help = true;
                }
                "version" => {
                    want_version = true;
                }
                _ => {
                    return clap_err_unknown(&prog_basename, &format!("--{}", name));
                }
            }
        } else if let Some(short) = tok.strip_prefix('-') {
            if short.is_empty() {
                positional.push(tok.to_string());
                continue;
            }
            // Handle combined short options like -cp
            let mut chars = short.chars().peekable();
            while let Some(ch) = chars.next() {
                match ch {
                    'c' => {
                        args.check = true;
                        cli_check = true;
                    }
                    'p' => {
                        args.print = true;
                        cli_print = true;
                    }
                    'f' => {
                        args.fail_on_change = true;
                        cli_fail = true;
                    }
