    }
}

fn resolve_filename(name: &str) -> PathBuf {
    let p = PathBuf::from(name);
    if p.extension().is_none() {
        // append .tex
        let mut s = name.to_string();
        s.push_str(".tex");
        PathBuf::from(s)
    } else {
        p
    }
}

fn is_valid_extension(p: &std::path::Path) -> bool {
    match p.extension().and_then(|e| e.to_str()) {
        Some("tex") | Some("bib") | Some("cls") | Some("sty") => true,
        _ => false,
    }
}

fn collect_recursive(base: &std::path::Path, out: &mut Vec<PathBuf>) {
    if base.is_file() {
        if is_valid_extension(base) {
            out.push(base.to_path_buf());
        }
        return;
    }
    if let Ok(entries) = std::fs::read_dir(base) {
        let mut list: Vec<_> = entries.flatten().collect();
        list.sort_by_key(|e| e.file_name());
        for e in list {
            let p = e.path();
            if p.is_dir() {
                collect_recursive(&p, out);
            } else if is_valid_extension(&p) {
                out.push(p);
            }
        }
    }
}

fn print_help(prog: &str) {
    let usage = format!("Usage: {} [OPTIONS] [files]...", prog);
    let body = format!(
        "tex-fmt 0.5.6

LaTeX formatter written in Rust

{}

Arguments:
  [files]...  List of files to be formatted

Options:
  -c, --check               Check formatting, do not modify files
  -p, --print               Print to stdout, do not modify files
  -f, --fail-on-change      Format files and return non-zero exit code if files are modified
  -n, --nowrap              Do not wrap long lines
  -l, --wraplen <N>         Line length for wrapping [default: 80]
  -t, --tabsize <N>         Number of characters to use as tab size [default: 2]
      --usetabs             Use tabs instead of spaces for indentation
  -s, --stdin               Process stdin as a single file, output to stdout
      --config <PATH>       Path to config file
      --noconfig            Do not read any config file
  -v, --verbose             Show info messages
  -q, --quiet               Hide warning messages
      --trace               Show trace messages
      --completion <SHELL>  Generate shell completion script [possible values: bash, elvish, fish, powershell, zsh]
      --man                 Generate man page
      --args                Print arguments passed to tex-fmt and exit
  -r, --recursive           Recursively search for files to format
  -h, --help                Print help
  -V, --version             Print version",
        usage
    );
    println!("{}", body);
}

fn clap_err_missing(prog: &str, opt: &str) -> ExitCode {
    let msg = format!(
        "error: a value is required for '{}' but none was supplied\n\nFor more information, try '--help'.\n",
        opt
    );
    let _ = std::io::stderr().write_all(msg.as_bytes());
    let _ = prog;
    ExitCode::from(2)
}

fn clap_err_invalid(prog: &str, opt: &str, val: &str, err: &str) -> ExitCode {
    let msg = format!(
        "error: invalid value '{}' for '{}': {}\n\nFor more information, try '--help'.\n",
        val, opt, err
    );
    let _ = std::io::stderr().write_all(msg.as_bytes());
    let _ = prog;
    ExitCode::from(2)
}

fn clap_err_invalid_choice(prog: &str, opt: &str, val: &str) -> ExitCode {
    let msg = format!(
        "error: invalid value '{}' for '{}'\n  [possible values: bash, elvish, fish, powershell, zsh]\n\nFor more information, try '--help'.\n",
        val, opt
    );
    let _ = std::io::stderr().write_all(msg.as_bytes());
    let _ = prog;
    ExitCode::from(2)
}

fn clap_err_unknown(prog: &str, arg: &str) -> ExitCode {
    let msg = format!(
        "error: unexpected argument '{}' found\n\nUsage: {} [OPTIONS] [files]...\n\nFor more information, try '--help'.\n",
        arg, prog
    );
    let _ = std::io::stderr().write_all(msg.as_bytes());
    ExitCode::from(2)
}
