    let mut want_help = false;
    let mut want_version = false;
    let mut want_args = false;
    let mut want_man = false;
    let mut completion_shell: Option<String> = None;
    let mut no_config = false;
    let mut noconfig_set = false;
    let mut wrap_set = false; // --nowrap used
    let mut cli_wraplen = false;
    let mut cli_wrapmin = false;
    let mut cli_tabsize = false;
    let mut cli_tabchar = false;
    let mut cli_stdin = false;
    let mut cli_verbosity = false;
    let mut cli_check = false;
    let mut cli_print = false;
    let mut cli_fail = false;
    let mut cli_recursive = false;

    let _ = noconfig_set;
    let _ = wrap_set;

    let mut positional = Vec::new();
    let mut only_positional = false;

