            let (name, inline_val) = match stripped.split_once('=') {
                Some((n, v)) => (n, Some(v.to_string())),
                None => (stripped, None),
            };
            match name {
                "check" => {
                    args.check = true;
                    cli_check = true;
                }
                "print" => {
                    args.print = true;
                    cli_print = true;
                }
                "fail-on-change" => {
                    args.fail_on_change = true;
                    cli_fail = true;
                }
                "nowrap" => {
                    args.wrap = false;
                    wrap_set = true;
                }
                "wraplen" => {
                    let v = match inline_val {
                        Some(v) => v,
                        None => match iter.next() {
                            Some(v) => v.clone(),
                            None => {
                                return clap_err_missing(&prog_basename, "--wraplen <N>");
                            }
                        },
                    };
                    match v.parse::<usize>() {
                        Ok(n) => {
                            args.wraplen = n;
                            args.recalc_wrapmin();
                            cli_wraplen = true;
                        }
                        Err(e) => {
                            return clap_err_invalid(
                                &prog_basename,
                                "--wraplen <N>",
                                &v,
                                &e.to_string(),
                            );
                        }
                    }
                }
                "tabsize" => {
                    let v = match inline_val {
                        Some(v) => v,
                        None => match iter.next() {
                            Some(v) => v.clone(),
                            None => {
                                return clap_err_missing(&prog_basename, "--tabsize <N>");
                            }
                        },
                    };
                    match v.parse::<usize>() {
                        Ok(n) => {
                            args.tabsize = n;
                            cli_tabsize = true;
                        }
                        Err(e) => {
                            return clap_err_invalid(
                                &prog_basename,
                                "--tabsize <N>",
                                &v,
                                &e.to_string(),
                            );
                        }
                    }
                }
                "usetabs" => {
                    args.tabchar = TabChar::Tab;
                    cli_tabchar = true;
                }
                "stdin" => {
                    args.stdin = true;
                    cli_stdin = true;
                }
                "config" => {
                    let v = match inline_val {
