                        None => match iter.next() {
                            Some(v) => v.clone(),
                            None => {
                                return clap_err_missing(&prog_basename, "--config <PATH>");
                            }
                        },
                    };
                    args.config_path = Some(v);
                }
                "noconfig" => {
                    no_config = true;
                    noconfig_set = true;
                }
                "verbose" => {
                    if args.verbosity < Verbosity::Info {
                        args.verbosity = Verbosity::Info;
                    }
                    cli_verbosity = true;
                }
                "quiet" => {
                    args.verbosity = Verbosity::Error;
                    cli_verbosity = true;
                }
                "trace" => {
                    args.verbosity = Verbosity::Trace;
                    cli_verbosity = true;
                }
                "completion" => {
                    let v = match inline_val {
                        Some(v) => v,
                        None => match iter.next() {
                            Some(v) => v.clone(),
                            None => {
                                return clap_err_missing(&prog_basename, "--completion <SHELL>");
                            }
                        },
                    };
                    completion_shell = Some(v);
                }
                "man" => {
                    want_man = true;
                }
                "args" => {
                    want_args = true;
                }
                "recursive" => {
                    args.recursive = true;
                    cli_recursive = true;
                }
                "help" => {
                    want_help = true;
                }
                "version" => {
                    want_version = true;
                }
                _ => {
                    return clap_err_unknown(&prog_basename, &format!("--{}", name));
                }
            }
        } else if let Some(short) = tok.strip_prefix('-') {
            if short.is_empty() {
                positional.push(tok.to_string());
                continue;
            }
            // Handle combined short options like -cp
            let mut chars = short.chars().peekable();
            while let Some(ch) = chars.next() {
                match ch {
                    'c' => {
                        args.check = true;
                        cli_check = true;
                    }
                    'p' => {
                        args.print = true;
                        cli_print = true;
                    }
                    'f' => {
                        args.fail_on_change = true;
                        cli_fail = true;
                    }
                    'n' => {
                        args.wrap = false;
                        wrap_set = true;
                    }
                    's' => {
                        args.stdin = true;
                        cli_stdin = true;
                    }
                    'v' => {
                        if args.verbosity < Verbosity::Info {
                            args.verbosity = Verbosity::Info;
                        }
                        cli_verbosity = true;
                    }
                    'q' => {
                        args.verbosity = Verbosity::Error;
                        cli_verbosity = true;
                    }
                    'r' => {
                        args.recursive = true;
                        cli_recursive = true;
                    }
                    'h' => {
                        want_help = true;
                    }
                    'V' => {
                        want_version = true;
                    }
                    'l' => {
                        let rest: String = chars.clone().collect();
                        let val = if !rest.is_empty() {
                            chars.by_ref().for_each(|_| {});
                            rest
                        } else {
                            match iter.next() {
                                Some(v) => v.clone(),
                                None => {
                                    return clap_err_missing(&prog_basename, "--wraplen <N>");
                                }
                            }
