        return ExitCode::SUCCESS;
    }
    if want_man {
        print!("{}", man::man_page());
        return ExitCode::SUCCESS;
    }
    if let Some(shell) = completion_shell {
        match shell.as_str() {
            "bash" => print!("{}", completion::bash()),
            "zsh" => print!("{}", completion::zsh()),
            "fish" => print!("{}", completion::fish()),
            "elvish" => print!("{}", completion::elvish()),
            "powershell" => print!("{}", completion::powershell()),
            _ => {
                return clap_err_invalid_choice(
                    &prog_basename,
                    "--completion <SHELL>",
                    &shell,
                );
            }
        }
        return ExitCode::SUCCESS;
    }

    // Apply config file unless --noconfig
    if !no_config {
        // Save CLI values, then apply config, then restore CLI values
        let cli = args.clone();
        if let Err(e) = config::apply_config(&mut args) {
            logger::error("", &e);
            return ExitCode::from(1);
        }
        // Restore CLI-set options
        if cli_check { args.check = cli.check; }
        if cli_print { args.print = cli.print; }
        if cli_fail { args.fail_on_change = cli.fail_on_change; }
        if wrap_set { args.wrap = cli.wrap; }
        if cli_wraplen {
            args.wraplen = cli.wraplen;
            args.recalc_wrapmin();
        }
        if cli_wrapmin { args.wrapmin = cli.wrapmin; }
        if cli_tabsize { args.tabsize = cli.tabsize; }
        if cli_tabchar { args.tabchar = cli.tabchar; }
        if cli_stdin { args.stdin = cli.stdin; }
        if cli_verbosity { args.verbosity = cli.verbosity; }
        if cli_recursive { args.recursive = cli.recursive; }
    }

    if want_args {
        print!("{}", args.format_args_display(!args.files.is_empty()));
        return ExitCode::SUCCESS;
    }

    logger::init(args.verbosity);

    // Validate
    if args.stdin && !args.files.is_empty() {
        logger::error("", "Do not provide file name(s) when using --stdin.");
        return ExitCode::from(1);
    }
    if !args.stdin && !args.recursive && args.files.is_empty() {
        logger::error(
            "",
            "No files specified. Provide filenames, or pass --recursive or --stdin.",
        );
        return ExitCode::from(1);
    }

    // Handle --stdin
    if args.stdin {
        let mut input = String::new();
        if io::stdin().read_to_string(&mut input).is_err() {
            logger::error("", "Failed to read from stdin.");
            return ExitCode::from(1);
        }
        let out = format::format(&input, &args);
        if args.print || (!args.check && !args.fail_on_change) {
            let _ = io::stdout().write_all(out.as_bytes());
        }
        if args.check && out != input {
            logger::error("<stdin>", "Incorrect formatting.");
            return ExitCode::from(1);
        }
