        let bases: Vec<PathBuf> = if args.files.is_empty() {
            vec![PathBuf::from(".")]
        } else {
            args.files.iter().map(PathBuf::from).collect()
        };
        for b in &bases {
            collect_recursive(b, &mut files);
        }
    } else {
        for f in &args.files {
            let p = resolve_filename(f);
            files.push(p);
        }
    }

    let mut any_error = false;
    for path in &files {
        let label = path.to_string_lossy().to_string();
