                        let _ = std::fs::write(path, &out);
                        if args.fail_on_change {
                            any_error = true;
                        }
                    }
                }
            }
        }
    }

    if any_error {
        ExitCode::from(1)
    } else {
        ExitCode::SUCCESS
    }
}

