    let mut only_positional = false;

    while let Some(tok_raw) = iter.next() {
        let tok = tok_raw.as_str();
        if only_positional {
            positional.push(tok.to_string());
            continue;
        }
        if tok == "--" {
            only_positional = true;
            continue;
        }
        // Long options possibly with =val
        if let Some(stripped) = tok.strip_prefix("--") {
            let (name, inline_val) = match stripped.split_once('=') {
                Some((n, v)) => (n, Some(v.to_string())),
                None => (stripped, None),
            };
            match name {
                "check" => {
                    args.check = true;
                    cli_check = true;
                }
                "print" => {
                    args.print = true;
                    cli_print = true;
                }
                "fail-on-change" => {
                    args.fail_on_change = true;
                    cli_fail = true;
                }
                "nowrap" => {
                    args.wrap = false;
                    wrap_set = true;
                }
                "wraplen" => {
                    let v = match inline_val {
                        Some(v) => v,
                        None => match iter.next() {
                            Some(v) => v.clone(),
                            None => {
                                return clap_err_missing(&prog_basename, "--wraplen <N>");
                            }
                        },
                    };
                    match v.parse::<usize>() {
                        Ok(n) => {
                            args.wraplen = n;
                            args.recalc_wrapmin();
                            cli_wraplen = true;
                        }
                        Err(e) => {
                            return clap_err_invalid(
                                &prog_basename,
                                "--wraplen <N>",
                                &v,
                                &e.to_string(),
                            );
                        }
                    }
                }
                "tabsize" => {
                    let v = match inline_val {
                        Some(v) => v,
                        None => match iter.next() {
                            Some(v) => v.clone(),
                            None => {
                                return clap_err_missing(&prog_basename, "--tabsize <N>");
                            }
                        },
                    };
                    match v.parse::<usize>() {
                        Ok(n) => {
                            args.tabsize = n;
                            cli_tabsize = true;
                        }
                        Err(e) => {
                            return clap_err_invalid(
                                &prog_basename,
                                "--tabsize <N>",
                                &v,
                                &e.to_string(),
                            );
                        }
                    }
                }
                "usetabs" => {
                    args.tabchar = TabChar::Tab;
                    cli_tabchar = true;
                }
                "stdin" => {
                    args.stdin = true;
                    cli_stdin = true;
                }
                "config" => {
                    let v = match inline_val {
                        Some(v) => v,
                        None => match iter.next() {
                            Some(v) => v.clone(),
                            None => {
                                return clap_err_missing(&prog_basename, "--config <PATH>");
                            }
                        },
                    };
                    args.config_path = Some(v);
                }
                "noconfig" => {
                    no_config = true;
                    noconfig_set = true;
                }
                "verbose" => {
                    if args.verbosity < Verbosity::Info {
                        args.verbosity = Verbosity::Info;
                    }
                    cli_verbosity = true;
                }
                "quiet" => {
                    args.verbosity = Verbosity::Error;
                    cli_verbosity = true;
                }
                "trace" => {
                    args.verbosity = Verbosity::Trace;
                    cli_verbosity = true;
                }
                "completion" => {
                    let v = match inline_val {
                        Some(v) => v,
                        None => match iter.next() {
                            Some(v) => v.clone(),
                            None => {
                                return clap_err_missing(&prog_basename, "--completion <SHELL>");
                            }
                        },
                    };
                    completion_shell = Some(v);
                }
                "man" => {
                    want_man = true;
                }
                "args" => {
                    want_args = true;
                }
                "recursive" => {
                    args.recursive = true;
                    cli_recursive = true;
                }
                "help" => {
                    want_help = true;
                }
                "version" => {
                    want_version = true;
                }
                _ => {
                    return clap_err_unknown(&prog_basename, &format!("--{}", name));
                }
            }
        } else if let Some(short) = tok.strip_prefix('-') {
            if short.is_empty() {
                positional.push(tok.to_string());
                continue;
            }
            // Handle combined short options like -cp
            let mut chars = short.chars().peekable();
            while let Some(ch) = chars.next() {
                match ch {
                    'c' => {
                        args.check = true;
                        cli_check = true;
                    }
                    'p' => {
                        args.print = true;
                        cli_print = true;
                    }
                    'f' => {
                        args.fail_on_change = true;
                        cli_fail = true;
                    }
                    'n' => {
                        args.wrap = false;
                        wrap_set = true;
                    }
                    's' => {
                        args.stdin = true;
                        cli_stdin = true;
                    }
                    'v' => {
                        if args.verbosity < Verbosity::Info {
                            args.verbosity = Verbosity::Info;
                        }
                        cli_verbosity = true;
                    }
                    'q' => {
                        args.verbosity = Verbosity::Error;
                        cli_verbosity = true;
                    }
                    'r' => {
                        args.recursive = true;
                        cli_recursive = true;
                    }
                    'h' => {
                        want_help = true;
                    }
                    'V' => {
                        want_version = true;
                    }
                    'l' => {
                        let rest: String = chars.clone().collect();
                        let val = if !rest.is_empty() {
                            chars.by_ref().for_each(|_| {});
                            rest
                        } else {
                            match iter.next() {
                                Some(v) => v.clone(),
                                None => {
                                    return clap_err_missing(&prog_basename, "--wraplen <N>");
                                }
                            }
                        };
                        match val.parse::<usize>() {
                            Ok(n) => {
                                args.wraplen = n;
                                args.recalc_wrapmin();
                                cli_wraplen = true;
                            }
                            Err(e) => {
                                return clap_err_invalid(
                                    &prog_basename,
                                    "--wraplen <N>",
                                    &val,
                                    &e.to_string(),
                                );
                            }
                        }
                        break;
                    }
                    't' => {
                        let rest: String = chars.clone().collect();
                        let val = if !rest.is_empty() {
                            chars.by_ref().for_each(|_| {});
                            rest
                        } else {
                            match iter.next() {
                                Some(v) => v.clone(),
                                None => {
                                    return clap_err_missing(&prog_basename, "--tabsize <N>");
                                }
                            }
                        };
                        match val.parse::<usize>() {
                            Ok(n) => {
                                args.tabsize = n;
                                cli_tabsize = true;
                            }
                            Err(e) => {
                                return clap_err_invalid(
                                    &prog_basename,
                                    "--tabsize <N>",
                                    &val,
                                    &e.to_string(),
                                );
                            }
                        }
                        break;
                    }
                    _ => {
                        return clap_err_unknown(&prog_basename, &format!("-{}", ch));
                    }
                }
            }
        } else {
            positional.push(tok.to_string());
        }
    }

    args.files = positional;

    // Immediate actions
    if want_help {
        print_help(&prog_basename);
        return ExitCode::SUCCESS;
    }
    if want_version {
        println!("tex-fmt 0.5.6");
        return ExitCode::SUCCESS;
    }
    if want_man {
        print!("{}", man::man_page());
        return ExitCode::SUCCESS;
    }
    if let Some(shell) = completion_shell {
        match shell.as_str() {
            "bash" => print!("{}", completion::bash()),
            "zsh" => print!("{}", completion::zsh()),
            "fish" => print!("{}", completion::fish()),
            "elvish" => print!("{}", completion::elvish()),
            "powershell" => print!("{}", completion::powershell()),
            _ => {
                return clap_err_invalid_choice(
                    &prog_basename,
                    "--completion <SHELL>",
                    &shell,
                );
            }
        }
        return ExitCode::SUCCESS;
    }

    // Apply config file unless --noconfig
    if !no_config {
        // Save CLI values, then apply config, then restore CLI values
        let cli = args.clone();
        if let Err(e) = config::apply_config(&mut args) {
            logger::error("", &e);
            return ExitCode::from(1);
        }
        // Restore CLI-set options
        if cli_check { args.check = cli.check; }
        if cli_print { args.print = cli.print; }
        if cli_fail { args.fail_on_change = cli.fail_on_change; }
        if wrap_set { args.wrap = cli.wrap; }
        if cli_wraplen {
            args.wraplen = cli.wraplen;
            args.recalc_wrapmin();
        }
        if cli_wrapmin { args.wrapmin = cli.wrapmin; }
        if cli_tabsize { args.tabsize = cli.tabsize; }
        if cli_tabchar { args.tabchar = cli.tabchar; }
        if cli_stdin { args.stdin = cli.stdin; }
        if cli_verbosity { args.verbosity = cli.verbosity; }
        if cli_recursive { args.recursive = cli.recursive; }
    }

    if want_args {
        print!("{}", args.format_args_display(!args.files.is_empty()));
        return ExitCode::SUCCESS;
    }

    logger::init(args.verbosity);

    // Validate
    if args.stdin && !args.files.is_empty() {
        logger::error("", "Do not provide file name(s) when using --stdin.");
        return ExitCode::from(1);
    }
    if !args.stdin && !args.recursive && args.files.is_empty() {
        logger::error(
            "",
            "No files specified. Provide filenames, or pass --recursive or --stdin.",
        );
        return ExitCode::from(1);
    }

    // Handle --stdin
    if args.stdin {
        let mut input = String::new();
        if io::stdin().read_to_string(&mut input).is_err() {
            logger::error("", "Failed to read from stdin.");
            return ExitCode::from(1);
        }
        let out = format::format(&input, &args);
        if args.print || (!args.check && !args.fail_on_change) {
            let _ = io::stdout().write_all(out.as_bytes());
        }
        if args.check && out != input {
            logger::error("<stdin>", "Incorrect formatting.");
            return ExitCode::from(1);
        }
        return ExitCode::SUCCESS;
    }

    // Collect files (with recursive)
    let mut files: Vec<PathBuf> = Vec::new();
    if args.recursive {
        let bases: Vec<PathBuf> = if args.files.is_empty() {
            vec![PathBuf::from(".")]
        } else {
            args.files.iter().map(PathBuf::from).collect()
        };
        for b in &bases {
            collect_recursive(b, &mut files);
        }
    } else {
        for f in &args.files {
            let p = resolve_filename(f);
            files.push(p);
        }
    }

    let mut any_error = false;
    for path in &files {
        let label = path.to_string_lossy().to_string();
        if path.is_dir() {
            logger::error("", "A directory was passed without --recursive.");
            any_error = true;
            continue;
        }
        if !is_valid_extension(path) {
            logger::error(&label, "File type invalid.");
            any_error = true;
            continue;
        }
        match std::fs::read_to_string(path) {
            Err(_) => {
                logger::error(&label, "Could not open file.");
                any_error = true;
            }
            Ok(content) => {
                logger::info(&label, "Formatting started.");
                let out = format::format(&content, &args);
                logger::info(&label, "Formatting complete.");
                if args.check {
                    if out != content {
                        logger::error(&label, "Incorrect formatting.");
                        any_error = true;
                    }
                } else if args.print {
                    let _ = io::stdout().write_all(out.as_bytes());
                } else {
                    let changed = out != content;
                    if changed {
                        let _ = std::fs::write(path, &out);
                        if args.fail_on_change {
                            any_error = true;
                        }
                    }
                }
            }
        }
    }

    if any_error {
        ExitCode::from(1)
    } else {
        ExitCode::SUCCESS
    }
}

fn resolve_filename(name: &str) -> PathBuf {
    let p = PathBuf::from(name);
    if p.extension().is_none() {
        // append .tex
        let mut s = name.to_string();
        s.push_str(".tex");
        PathBuf::from(s)
    } else {
        p
    }
}

fn is_valid_extension(p: &std::path::Path) -> bool {
    match p.extension().and_then(|e| e.to_str()) {
        Some("tex") | Some("bib") | Some("cls") | Some("sty") => true,
        _ => false,
    }
}

fn collect_recursive(base: &std::path::Path, out: &mut Vec<PathBuf>) {
    if base.is_file() {
        if is_valid_extension(base) {
            out.push(base.to_path_buf());
        }
        return;
    }
    if let Ok(entries) = std::fs::read_dir(base) {
        let mut list: Vec<_> = entries.flatten().collect();
        list.sort_by_key(|e| e.file_name());
        for e in list {
            let p = e.path();
            if p.is_dir() {
                collect_recursive(&p, out);
            } else if is_valid_extension(&p) {
                out.push(p);
            }
        }
    }
}

fn print_help(prog: &str) {
    let usage = format!("Usage: {} [OPTIONS] [files]...", prog);
    let body = format!(
        "tex-fmt 0.5.6

LaTeX formatter written in Rust

{}

Arguments:
  [files]...  List of files to be formatted

Options:
  -c, --check               Check formatting, do not modify files
  -p, --print               Print to stdout, do not modify files
  -f, --fail-on-change      Format files and return non-zero exit code if files are modified
  -n, --nowrap              Do not wrap long lines
  -l, --wraplen <N>         Line length for wrapping [default: 80]
  -t, --tabsize <N>         Number of characters to use as tab size [default: 2]
      --usetabs             Use tabs instead of spaces for indentation
  -s, --stdin               Process stdin as a single file, output to stdout
