fn clap_err_missing(prog: &str, opt: &str) -> ExitCode {
    let msg = format!(
        "error: a value is required for '{}' but none was supplied\n\nFor more information, try '--help'.\n",
        opt
    );
    let _ = std::io::stderr().write_all(msg.as_bytes());
    let _ = prog;
    ExitCode::from(2)
}

fn clap_err_invalid(prog: &str, opt: &str, val: &str, err: &str) -> ExitCode {
    let msg = format!(
        "error: invalid value '{}' for '{}': {}\n\nFor more information, try '--help'.\n",
        val, opt, err
    );
    let _ = std::io::stderr().write_all(msg.as_bytes());
    let _ = prog;
    ExitCode::from(2)
}

fn clap_err_invalid_choice(prog: &str, opt: &str, val: &str) -> ExitCode {
    let msg = format!(
        "error: invalid value '{}' for '{}'\n  [possible values: bash, elvish, fish, powershell, zsh]\n\nFor more information, try '--help'.\n",
        val, opt
    );
    let _ = std::io::stderr().write_all(msg.as_bytes());
    let _ = prog;
    ExitCode::from(2)
}

fn clap_err_unknown(prog: &str, arg: &str) -> ExitCode {
    let msg = format!(
        "error: unexpected argument '{}' found\n\nUsage: {} [OPTIONS] [files]...\n\nFor more information, try '--help'.\n",
        arg, prog
    );
    let _ = std::io::stderr().write_all(msg.as_bytes());
    ExitCode::from(2)
}
