//! Main formatting logic.

use crate::args::{Args, TabChar};
use crate::wrap;

/// Entry point: format a file's content.
pub fn format(input: &str, args: &Args) -> String {
    // Normalize line endings: CRLF -> LF, CR -> LF.
    let input = normalize_line_endings(input);
    let lines: Vec<&str> = input.split('\n').collect();
    // If input ends with \n, last element is empty string. Preserve that.

    // Track trailing empty element for final newline.
    let ends_with_newline = input.ends_with('\n');
    let mut working: Vec<String> = if ends_with_newline {
        lines[..lines.len() - 1].iter().map(|s| s.to_string()).collect()
    } else {
        lines.iter().map(|s| s.to_string()).collect()
    };

    // Pass 1: collapse multiple blank lines and strip trailing whitespace,
    // strip leading whitespace (we'll re-add indent).
    let mut processed: Vec<String> = Vec::with_capacity(working.len());
    let mut prev_blank = false;
    for line in working.drain(..) {
        let stripped = strip_trailing_ws(&line);
        let is_blank = stripped.trim().is_empty();
        if is_blank {
            if !prev_blank {
                processed.push(String::new());
            }
            prev_blank = true;
        } else {
            processed.push(stripped);
            prev_blank = false;
        }
    }
    // Remove trailing blank lines
    while processed.last().map_or(false, |l| l.trim().is_empty()) {
        processed.pop();
    }

    // Pass 2: compute indentation
    let mut indented = indent_lines(&processed, args);

    // Pass 3: line wrapping
    if args.wrap {
        indented = wrap::wrap_lines(&indented, args);
    }

    // Join with \n and add trailing newline if non-empty
    let mut out = indented.join("\n");
    if !out.is_empty() {
        out.push('\n');
    }
    out
}

fn normalize_line_endings(s: &str) -> String {
    // Replace \r\n and \r with \n.
    let mut result = String::with_capacity(s.len());
    let mut chars = s.chars().peekable();
    while let Some(c) = chars.next() {
        if c == '\r' {
            if chars.peek() == Some(&'\n') {
                chars.next();
            }
            result.push('\n');
        } else {
            result.push(c);
        }
    }
    result
}

fn strip_trailing_ws(s: &str) -> String {
    s.trim_end_matches(|c: char| c == ' ' || c == '\t').to_string()
}

#[derive(Clone, Copy)]
struct IndentState {
    level: i32,
    item_level: i32, // extra indent for item continuation
    in_verbatim: bool,
    verbatim_env: String_,
}

#[allow(non_camel_case_types)]
type String_ = Option<String>;

fn make_indent(level: i32, args: &Args) -> String {
    if level <= 0 {
        return String::new();
    }
    let n = level as usize;
    match args.tabchar {
        TabChar::Tab => "\t".repeat(n),
        TabChar::Space => " ".repeat(n * args.tabsize),
    }
}

fn indent_lines(lines: &[String], args: &Args) -> Vec<String> {
    let mut result: Vec<String> = Vec::with_capacity(lines.len());

    // Track stack of environments for item indentation
    let mut env_stack: Vec<(String, bool)> = Vec::new(); // (env_name, is_list)
    let mut item_after_begin: Vec<bool> = Vec::new();
    let mut in_verbatim: Option<String> = None;
    let mut brace_depth: i32 = 0;
    let mut level: i32 = 0;

    // For checking for list environments
    let is_list = |name: &str| args.lists.iter().any(|l| l == name);
    let is_verbatim = |name: &str| args.verbatims.iter().any(|l| l == name);
    let is_no_indent = |name: &str| args.no_indent_envs.iter().any(|l| l == name);

    for raw in lines.iter() {
        // If blank, just pass through.
        if raw.trim().is_empty() {
            result.push(String::new());
            continue;
        }

        // If in verbatim, pass through as-is
        if let Some(env) = &in_verbatim {
            // Check for \end{env}
            let trimmed = raw.trim_start();
            let end_marker = format!("\\end{{{}}}", env);
            if trimmed.starts_with(&end_marker) {
                in_verbatim = None;
                // let this line go through indentation calculation below
                // but for simplicity, output trimmed? Actually the \end
                // should be at the current indent level (same as \begin)
                // Emit with indent:
                let ind = make_indent(level, args);
                result.push(format!("{}{}", ind, trimmed));
                // Pop env_stack/item_after_begin
                if !env_stack.is_empty() {
                    env_stack.pop();
                    item_after_begin.pop();
                }
                continue;
            } else {
                // preserve as-is
                result.push(raw.clone());
                continue;
            }
        }

        let content = raw.trim_start();

        // Determine this line's indent adjustments BEFORE emitting.
        let starts_with_end = content.starts_with("\\end{");
        let starts_with_close_brace = content.starts_with('}');

        let mut this_level = level;

        // Item indentation: if we're in a list env and this line is not a \item,
        // and not \begin/\end, then it's a continuation of the last item.
        let cur_is_item = content.starts_with("\\item");

        // Handle \end: decrement first
        if starts_with_end {
            // figure out env name
            if let Some(name) = extract_env_name(content, "end") {
                if is_no_indent(&name) {
                    // don't change level
                } else {
                    this_level = (this_level - 1).max(0);
                    level = this_level;
                }
                if !env_stack.is_empty() {
                    env_stack.pop();
                    item_after_begin.pop();
                }
            }
        }
        if starts_with_close_brace {
            this_level = (this_level - 1).max(0);
            level = this_level;
        }

        // Item continuation: if the last env on stack is a list and item has been seen
        let mut extra = 0i32;
        if !cur_is_item && !starts_with_end {
            if let Some(idx) = env_stack.iter().rposition(|(_, is_lst)| *is_lst) {
                if item_after_begin.get(idx).copied().unwrap_or(false) {
                    // This line is indented one more level
                    extra = 1;
                }
            }
        }

        let eff_level = this_level + extra;
        let ind = make_indent(eff_level, args);
        result.push(format!("{}{}", ind, content));

        // Now update state based on line content.
        // Find all \begin{X} and \end{X} and { } outside of comments/verbatim.
        let code_part = strip_comment(content);

        // Scan for begin/end/braces
        let mut i = 0;
        let bytes = code_part.as_bytes();
        while i < bytes.len() {
            let c = bytes[i] as char;
            if c == '\\' && i + 1 < bytes.len() {
                // is it \begin{X} or \end{X}?
                if code_part[i..].starts_with("\\begin{") {
                    let rest = &code_part[i + 7..];
                    if let Some(end) = rest.find('}') {
                        let name = &rest[..end];
                        let is_verb = is_verbatim(name);
                        let is_lst = is_list(name);
                        let is_noidx = is_no_indent(name);
                        if is_verb {
                            in_verbatim = Some(name.to_string());
                        }
                        env_stack.push((name.to_string(), is_lst));
                        item_after_begin.push(false);
                        if !is_verb && !is_noidx {
                            level += 1;
                        }
                        i += 7 + end + 1;
                        continue;
                    } else {
                        i += 7;
                        continue;
                    }
                } else if code_part[i..].starts_with("\\end{") {
                    let rest = &code_part[i + 5..];
                    if let Some(end) = rest.find('}') {
                        // Already popped above; skip.
                        i += 5 + end + 1;
                        continue;
                    } else {
                        i += 5;
                        continue;
                    }
                } else if code_part[i..].starts_with("\\item") {
                    // Mark topmost list
