//! Line wrapping.

use crate::args::Args;

pub fn wrap_lines(lines: &[String], args: &Args) -> Vec<String> {
    let mut result: Vec<String> = Vec::with_capacity(lines.len());
    for line in lines {
        if line.trim().is_empty() {
            result.push(String::new());
            continue;
        }
        let wrapped = wrap_one(line, args);
        for w in wrapped {
            result.push(w);
        }
    }
    result
}

fn char_count(s: &str) -> usize {
    s.chars().count()
}

fn line_indent(s: &str) -> String {
    s.chars()
        .take_while(|c| *c == ' ' || *c == '\t')
        .collect()
}

fn wrap_one(line: &str, args: &Args) -> Vec<String> {
    if char_count(line) <= args.wraplen {
        return vec![line.to_string()];
    }
    let is_comment_line = line.trim_start().starts_with('%');
    let indent = line_indent(line);
    let rest_start = indent.len();
    let content = &line[rest_start..];
    // Continuation prefix
    let cont_prefix = if is_comment_line {
        // Comments: continue with same indent and "% " prefix.
        format!("{}%", indent)
    } else {
        indent.clone()
    };

    // Build word list preserving spaces
    let mut words: Vec<String> = Vec::new();
    let mut cur = String::new();
    for c in content.chars() {
        if c == ' ' {
            if !cur.is_empty() {
                words.push(cur.clone());
                cur.clear();
            }
        } else {
            cur.push(c);
        }
    }
    if !cur.is_empty() {
        words.push(cur);
    }

    if words.is_empty() {
        return vec![line.to_string()];
    }

    // For comment lines, treat first word as "%" since we already have '%' in content.
    let (first_prefix, words_to_wrap): (String, Vec<String>) = if is_comment_line {
        // The content starts with '%', words[0] starts with %. Keep the first line's "%" prefix.
        // Remove the leading "%" from first word and use it as prefix.
        let w0 = &words[0];
        if w0 == "%" {
            (format!("{}%", indent), words[1..].to_vec())
        } else if w0.starts_with('%') {
            // like "%foo" - keep as is
            (format!("{}", indent), words)
        } else {
            (format!("{}", indent), words)
        }
    } else {
        (indent.clone(), words)
    };

    // Greedy wrap based on wraplen
    let mut result: Vec<String> = Vec::new();
    let mut cur_line = first_prefix.clone();
    let mut cur_words_on_line = 0;
    for w in &words_to_wrap {
        let next_len = if cur_words_on_line == 0 {
            char_count(&cur_line) + char_count(w)
        } else {
            char_count(&cur_line) + 1 + char_count(w)
        };
        if cur_words_on_line > 0 && next_len > args.wraplen {
            result.push(cur_line.clone());
            cur_line = if is_comment_line {
                format!("{}%", indent)
            } else {
                indent.clone()
            };
            cur_words_on_line = 0;
        }
        if cur_words_on_line > 0 || !cur_line.is_empty() && !cur_line.ends_with(' ') && !cur_line.ends_with('%') {
            // add separator space
            cur_line.push(' ');
        } else if is_comment_line && cur_line.ends_with('%') {
            cur_line.push(' ');
        }
        cur_line.push_str(w);
        cur_words_on_line += 1;
    }
    if !cur_line.is_empty() {
        result.push(cur_line);
    }
    let _ = cont_prefix;
    result
}
