//! Main formatting logic.

use crate::args::{Args, TabChar};
use crate::wrap;

/// Entry point: format a file's content.
pub fn format(input: &str, args: &Args) -> String {
    let input = normalize_line_endings(input);
    let ends_with_newline = input.ends_with('\n');
    let lines: Vec<&str> = input.split('\n').collect();
    let working: Vec<&str> = if ends_with_newline {
        lines[..lines.len() - 1].to_vec()
    } else {
        lines
    };

    // Strip trailing whitespace, collapse consecutive blank lines, trim trailing blanks.
    let mut processed: Vec<String> = Vec::with_capacity(working.len());
    let mut prev_blank = false;
    for line in &working {
        let stripped = strip_trailing_ws(line);
        let is_blank = stripped.trim().is_empty();
        if is_blank {
            if !prev_blank {
                processed.push(String::new());
            }
            prev_blank = true;
        } else {
            processed.push(stripped);
            prev_blank = false;
        }
    }
    while processed.last().map_or(false, |l| l.trim().is_empty()) {
        processed.pop();
    }

    // Compute indentation.
    let mut indented = indent_lines(&processed, args);

    // Line wrapping.
    if args.wrap {
        indented = wrap::wrap_lines(&indented, args);
    }

    let mut out = indented.join("\n");
    if !out.is_empty() {
        out.push('\n');
    }
    out
}

fn normalize_line_endings(s: &str) -> String {
    let mut result = String::with_capacity(s.len());
    let mut chars = s.chars().peekable();
    while let Some(c) = chars.next() {
        if c == '\r' {
            if chars.peek() == Some(&'\n') {
                chars.next();
            }
            result.push('\n');
        } else {
            result.push(c);
        }
    }
    result
}

fn strip_trailing_ws(s: &str) -> String {
    s.trim_end_matches(|c: char| c == ' ' || c == '\t').to_string()
}

fn make_indent(level: i32, args: &Args) -> String {
    if level <= 0 {
        return String::new();
    }
    let n = level as usize;
    match args.tabchar {
        TabChar::Tab => "\t".repeat(n),
        TabChar::Space => " ".repeat(n * args.tabsize),
    }
}

#[derive(Clone, Debug)]
struct EnvFrame {
    name: String,
    is_list: bool,
    is_noindent: bool,
    is_verbatim: bool,
    item_seen: bool,
}

fn indent_lines(lines: &[String], args: &Args) -> Vec<String> {
    let mut result: Vec<String> = Vec::with_capacity(lines.len());
    let mut env_stack: Vec<EnvFrame> = Vec::new();
    let mut brace_depth: i32 = 0;
    let mut level: i32 = 0;
    let mut in_verbatim_env: Option<String> = None;

    let is_list = |name: &str| args.lists.iter().any(|l| l == name);
    let is_verbatim = |name: &str| args.verbatims.iter().any(|l| l == name);
    let is_no_indent = |name: &str| args.no_indent_envs.iter().any(|l| l == name);

    for raw in lines.iter() {
        if raw.trim().is_empty() {
            result.push(String::new());
            continue;
        }

        // Handle verbatim pass-through.
        if let Some(env) = in_verbatim_env.clone() {
            let end_marker = format!("\\end{{{}}}", env);
            let trimmed_start = raw.trim_start();
            if trimmed_start.starts_with(&end_marker) {
                // Emit \end at the \begin's indent level.
                // Pop the env first (this env was pushed with no level change).
                in_verbatim_env = None;
                env_stack.pop();
                let emit_level = level;
                let extra = compute_extra(&env_stack, false, false);
                let ind = make_indent(emit_level + extra, args);
                result.push(format!("{}{}", ind, trimmed_start));
                continue;
            } else {
                result.push(raw.clone());
                continue;
            }
        }

        let content = raw.trim_start();
        let is_item_line = content.starts_with("\\item") && !content.starts_with("\\items");

        // Handle leading \end or leading \} for pre-emit level adjustment.
        let mut this_level = level;
        let mut this_brace = brace_depth;
        let mut popped_end: Option<EnvFrame> = None;

        let mut rest = content;
        if let Some(name) = strip_leading_end(rest) {
            // Pop
            let popped_idx = env_stack
                .iter()
                .rposition(|f| f.name == name);
            if let Some(idx) = popped_idx {
                let f = env_stack.remove(idx);
                let was_no = f.is_noindent || f.is_verbatim;
                popped_end = Some(f);
                if !was_no {
                    this_level = (this_level - 1).max(0);
                    level = this_level;
                }
            }
            rest = &rest["\\end{".len() + name.len() + 1..];
        } else {
            // Check for leading }'s that close braces (one per leading })
            // Simpler: handle just one leading } if brace_depth>0.
            let bytes = rest.as_bytes();
            let mut i = 0;
            while i < bytes.len() && bytes[i] == b'}' {
                if this_brace > 0 {
                    this_brace -= 1;
                    this_level = (this_level - 1).max(0);
                }
                i += 1;
            }
            brace_depth = this_brace;
            level = this_level;
            let _ = rest;
        }

