            let c = bytes[i] as char;
            if c == '\\' && i + 1 < bytes.len() {
                if code[i..].starts_with("\\begin{") {
                    let rest2 = &code[i + 7..];
                    if let Some(endp) = rest2.find('}') {
                        let name = &rest2[..endp];
                        let is_v = is_verbatim(name);
                        let is_l = is_list(name);
                        let is_n = is_no_indent(name);
                        env_stack.push(EnvFrame {
                            name: name.to_string(),
                            is_list: is_l,
                            is_noindent: is_n,
                            is_verbatim: is_v,
                            item_seen: false,
                        });
                        if is_v {
                            in_verbatim_env = Some(name.to_string());
                        } else if !is_n {
                            level += 1;
                        }
                        i += 7 + endp + 1;
                        continue;
                    } else {
                        i += 7;
                        continue;
                    }
                } else if code[i..].starts_with("\\end{") {
                    let rest2 = &code[i + 5..];
                    if let Some(endp) = rest2.find('}') {
                        let name = &rest2[..endp];
                        let popped_idx = env_stack
                            .iter()
                            .rposition(|f| f.name == name);
                        if let Some(idx) = popped_idx {
                            let f = env_stack.remove(idx);
                            if !(f.is_noindent || f.is_verbatim) {
                                level = (level - 1).max(0);
                            }
                        }
                        i += 5 + endp + 1;
                        continue;
                    } else {
                        i += 5;
                        continue;
                    }
                } else if code[i..].starts_with("\\item") {
                    if let Some(idx) =
                        env_stack.iter().rposition(|f| f.is_list)
                    {
                        env_stack[idx].item_seen = true;
                    }
                    i += 5;
                    continue;
                } else {
                    i += 2;
                    continue;
                }
            } else if c == '{' {
                brace_depth += 1;
                level += 1;
                i += 1;
            } else if c == '}' {
                if brace_depth > 0 {
                    brace_depth -= 1;
                    level = (level - 1).max(0);
                }
                i += 1;
            } else {
                i += 1;
            }
        }
    }

    result
}

/// Given current stack, compute extra indent from list continuations.
///
/// - `is_item`: true if the current line starts with `\item`. In this case,
///   the *topmost* list env does not contribute, because we are at an item
///   marker, not inside an item body.
/// - `is_end_popped`: true if an \end has been popped from the stack at the
///   start of this line. In that case, don't count the popped env.
fn compute_extra(stack: &[EnvFrame], is_item: bool, _is_end_popped: bool) -> i32 {
    if stack.is_empty() {
        return 0;
    }
    // Find the topmost list in the stack (rightmost).
    let topmost_list_idx = stack.iter().rposition(|f| f.is_list);

    let mut extra = 0;
    for (i, f) in stack.iter().enumerate() {
        if !f.is_list {
            continue;
        }
        if !f.item_seen {
            continue;
        }
        // If is_item and this is the topmost list, skip.
        if is_item && Some(i) == topmost_list_idx {
            continue;
        }
        extra += 1;
    }
    extra
}

fn strip_leading_end(s: &str) -> Option<String> {
    if !s.starts_with("\\end{") {
        return None;
    }
    let rest = &s[5..];
    let endp = rest.find('}')?;
    Some(rest[..endp].to_string())
}

fn strip_comment(s: &str) -> String {
    let mut out = String::new();
    let mut prev_backslash = false;
    for c in s.chars() {
        if c == '%' && !prev_backslash {
            break;
        }
        out.push(c);
        prev_backslash = c == '\\' && !prev_backslash;
    }
    out
}
