            prev_blank = false;
        }
    }
    while processed.last().map_or(false, |l| l.trim().is_empty()) {
        processed.pop();
    }

    // Compute indentation.
    let mut indented = indent_lines(&processed, args);

    // Line wrapping.
    if args.wrap {
        indented = wrap::wrap_lines(&indented, args);
    }

    let mut out = indented.join("\n");
    if !out.is_empty() {
        out.push('\n');
    }
