}

fn normalize_line_endings(s: &str) -> String {
    let mut result = String::with_capacity(s.len());
    let mut chars = s.chars().peekable();
    while let Some(c) = chars.next() {
        if c == '\r' {
            if chars.peek() == Some(&'\n') {
                chars.next();
            }
            result.push('\n');
        } else {
            result.push(c);
        }
    }
    result
}

fn strip_trailing_ws(s: &str) -> String {
    s.trim_end_matches(|c: char| c == ' ' || c == '\t').to_string()
}

fn make_indent(level: i32, args: &Args) -> String {
    if level <= 0 {
        return String::new();
    }
    let n = level as usize;
    match args.tabchar {
        TabChar::Tab => "\t".repeat(n),
        TabChar::Space => " ".repeat(n * args.tabsize),
    }
}

#[derive(Clone, Debug)]
struct EnvFrame {
