        let code = strip_comment(content);
        let bytes = code.as_bytes();
        let mut i = 0;
        // If we already popped at start, skip the leading \end{name} once.
        if let Some(ref f) = popped_end {
            let skip = "\\end{".len() + f.name.len() + 1;
            i = skip;
        }
