//! Line wrapping.

use crate::args::Args;

pub fn wrap_lines(lines: &[String], args: &Args) -> Vec<String> {
    let mut result: Vec<String> = Vec::with_capacity(lines.len());
    for line in lines {
        if line.trim().is_empty() {
            result.push(String::new());
            continue;
        }
        let mut pieces = wrap_one(line, args);
        result.append(&mut pieces);
    }
    result
}

fn char_count(s: &str) -> usize {
    s.chars().count()
}

fn leading_indent(s: &str) -> String {
    s.chars()
        .take_while(|c| *c == ' ' || *c == '\t')
        .collect()
}

/// Split line into indent + body.
fn split_line(s: &str) -> (String, String) {
    let ind = leading_indent(s);
    let rest = s[ind.len()..].to_string();
    (ind, rest)
}

/// Wrap one line into zero or more lines.
fn wrap_one(line: &str, args: &Args) -> Vec<String> {
    let mut out = Vec::new();
    let (indent, body) = split_line(line);
    let is_comment = body.starts_with('%');
    let mut remaining = body;
    let mut first = true;
    while !remaining.is_empty() {
        let (prefix, content) = if first || !is_comment {
            (indent.clone(), remaining.clone())
        } else {
            // Continuation of comment: add "% " prefix.
            (format!("{}% ", indent), remaining.clone())
        };
        let full_len = char_count(&prefix) + char_count(&content);
        if full_len <= args.wraplen {
            // Fits on a single line.
            out.push(format!("{}{}", prefix, content));
            break;
        }
        // Need to find break point in content.
        let prefix_len = char_count(&prefix);
        let wraplen = args.wraplen.saturating_sub(prefix_len);
        let wrapmin = args.wrapmin.saturating_sub(prefix_len);
        let break_p = find_break(&content, wraplen, wrapmin, &args.wrap_chars);
        match break_p {
            Some(p) => {
                let first_part = &content[..p];
                // Skip the break character (space or wrap_char).
                // If the break is a space, we drop it. Otherwise keep it in first part.
                // Simpler: find_break returns position where break *starts* (char at p is space).
                let ch_at_p = content[p..].chars().next().unwrap_or(' ');
                let (first_p, next_start) = if ch_at_p == ' ' {
                    (first_part.to_string(), p + 1)
                } else {
                    // Keep the wrap char at end of first part.
                    let end = p + ch_at_p.len_utf8();
                    (content[..end].to_string(), end)
                };
                out.push(format!("{}{}", prefix, first_p));
                remaining = content[next_start..].to_string();
                first = false;
            }
            None => {
                // Can't break; emit as-is.
                out.push(format!("{}{}", prefix, content));
                break;
            }
        }
    }
    out
}

fn find_break(s: &str, wraplen: usize, wrapmin: usize, wrap_chars: &[char]) -> Option<usize> {
    // Find positions of spaces (and wrap_chars) in char index.
    // Collect (byte_pos, char_pos) for spaces and wrap_chars.
    let mut breaks: Vec<(usize, usize, char)> = Vec::new();
    for (ci, (bi, c)) in s.char_indices().enumerate() {
        if c == ' ' || wrap_chars.contains(&c) {
            breaks.push((bi, ci, c));
        }
    }

    // Latest break with first_line_len < wrapmin.
    let mut best: Option<(usize, usize, char)> = None;
    for &(bi, ci, c) in &breaks {
        let first_len = ci; // chars before the space
        if first_len < wrapmin {
            best = Some((bi, ci, c));
        }
    }
    if let Some((bi, _, _)) = best {
        return Some(bi);
    }
    // Fallback: latest break with first_line_len <= wraplen.
    let mut best2: Option<(usize, usize, char)> = None;
    for &(bi, ci, c) in &breaks {
        let first_len = if c == ' ' { ci } else { ci + 1 };
        if first_len <= wraplen {
            best2 = Some((bi, ci, c));
        }
    }
    if let Some((bi, _, _)) = best2 {
        return Some(bi);
    }
    // Nothing fits; use first space.
    breaks.first().map(|(bi, _, _)| *bi)
}
