        TabChar::Space => " ".repeat(args.tabsize),
    }
}

fn wrap_one(line: &str, args: &Args) -> Vec<String> {
    let mut out = Vec::new();
    let (indent, body) = split_line(line);
    let is_comment = body.starts_with('%');
    let is_item = body.starts_with("\\item") && !body.starts_with("\\items");

    // Continuation prefix
    let cont_indent = if is_item {
        format!("{}{}", indent, tab(args))
    } else {
        indent.clone()
    };

    let mut remaining = body;
    let mut first = true;
    while !remaining.is_empty() {
        let prefix = if first {
            indent.clone()
        } else if is_comment {
            format!("{}% ", indent)
        } else {
            cont_indent.clone()
        };
        let full_len = char_count(&prefix) + char_count(&remaining);
        if full_len <= args.wraplen {
            out.push(format!("{}{}", prefix, remaining));
            break;
        }
        let prefix_len = char_count(&prefix);
        let wraplen = args.wraplen.saturating_sub(prefix_len);
        let wrapmin = args.wrapmin.saturating_sub(prefix_len);
        let break_p = find_break(&remaining, wraplen, wrapmin, &args.wrap_chars);
        match break_p {
            Some(p) => {
                let ch_at_p = remaining[p..].chars().next().unwrap_or(' ');
                let (first_p, next_start) = if ch_at_p == ' ' {
                    (remaining[..p].to_string(), p + 1)
                } else {
                    let end = p + ch_at_p.len_utf8();
                    (remaining[..end].to_string(), end)
                };
                out.push(format!("{}{}", prefix, first_p));
                remaining = remaining[next_start..].to_string();
                first = false;
            }
            None => {
                out.push(format!("{}{}", prefix, remaining));
                break;
            }
        }
    }
    out
}

fn find_break(s: &str, wraplen: usize, wrapmin: usize, wrap_chars: &[char]) -> Option<usize> {
    let mut breaks: Vec<(usize, usize, char)> = Vec::new();
    for (ci, (bi, c)) in s.char_indices().enumerate() {
        if c == ' ' || wrap_chars.contains(&c) {
            breaks.push((bi, ci, c));
        }
    }

    // Latest break with first_line_len < wrapmin.
    let mut best: Option<(usize, usize, char)> = None;
    for &(bi, ci, c) in &breaks {
        let first_len = ci;
        if first_len < wrapmin {
            best = Some((bi, ci, c));
        }
    }
    if let Some((bi, _, _)) = best {
        return Some(bi);
    }
    // Fallback: latest break with first_line_len <= wraplen.
    let mut best2: Option<(usize, usize, char)> = None;
    for &(bi, ci, c) in &breaks {
        let first_len = if c == ' ' { ci } else { ci + 1 };
        if first_len <= wraplen {
            best2 = Some((bi, ci, c));
        }
    }
    if let Some((bi, _, _)) = best2 {
        return Some(bi);
    }
    breaks.first().map(|(bi, _, _)| *bi)
}
